public sealed class ComponentBenchView {
 readonly ExpandedWorkshop shop;RaceProgressStore Store=>shop.Store;public string FocusedCar{get;private set;}public bool HasConfirmation=>pendingCar!=null;public string Message{get;private set;}
 string pendingCar,pendingSlot,pendingPart,dragSlot,dragPart;int fee;Vector2 scroll,carsScroll;struct Handle{public Rect rect;public string slot,part;}readonly List<Handle> handles=new List<Handle>();
 public ComponentBenchView(ExpandedWorkshop owner){shop=owner;}public void Open(string car){FocusedCar=car??Store.Profile.fleet.cars.FirstOrDefault(c=>c.owner=="player")?.id;pendingCar=dragSlot=dragPart=null;Message=null;}
 public void Focus(string car){if(FleetLedger.Find(Store.Profile.fleet,car).owner!="player")throw new InvalidOperationException("Car not owned");FocusedCar=car;}
 bool Allowed(){if(!shop.IsOpen||shop.IsTest||shop.Car.SpeedKph>=5){Message="Stop inside the garage before working on paid components.";return false;}return true;}
 public bool BeginRemove(string car,string slot){if(!Allowed())return false;try{fee=Store.ComponentRemovalFee(car,slot);pendingCar=car;pendingSlot=slot;pendingPart=null;Message=null;return true;}catch(Exception e){Message=e.Message;return false;}}
 public bool BeginFit(string part,string car){if(!Allowed())return false;try{fee=Store.ComponentFitFee(part,car);pendingCar=car;pendingPart=part;pendingSlot=null;Message=null;return true;}catch(Exception e){Message=e.Message;return false;}}
 public bool Confirm(){if(!Allowed()||pendingCar==null)return false;try{if(pendingPart==null)Store.RemoveComponent(Guid.NewGuid().ToString("N"),pendingCar,pendingSlot,fee);else Store.FitComponent(Guid.NewGuid().ToString("N"),pendingPart,pendingCar,fee);FocusedCar=pendingCar;pendingCar=null;shop.RefreshOwnedVehicle();Message="Labor paid and saved. The same kit retains its stage and identity.";return true;}catch(Exception e){Message=e.Message;return false;}}
