 static string Title(string slot,string choice,int stage)=>slot=="induction"?(choice=="roots"?"Roots supercharger":choice=="twin"?"Twin-turbo kit":choice=="large"?"Large turbo":choice=="small"?"Small turbo":"Factory induction")+" · S"+stage:(slot=="cooling"?"Intercooler":slot=="intake"?"Intake":"Exhaust")+" · S"+stage;
 static void Fill(Rect r,Color c){var old=GUI.color;GUI.color=c;GUI.DrawTexture(r,Texture2D.whiteTexture);GUI.color=old;}static GUIStyle Text(int size=17,bool bold=false){var s=new GUIStyle(GUI.skin.label){fontSize=size,wordWrap=true,fontStyle=bold?FontStyle.Bold:FontStyle.Normal};s.normal.textColor=Color.white;return s;}static void Label(Rect r,string text,int size=17,bool bold=false)=>GUI.Label(r,text,Text(size,bold));
 public void Draw(){var old=GUI.matrix;var color=GUI.backgroundColor;GUI.depth=-1250;GUI.matrix=Matrix4x4.Scale(new Vector3(Screen.width/1280f,Screen.height/800f,1));handles.Clear();Fill(new Rect(0,0,1280,800),new Color(.035f,.06f,.085f));Label(new Rect(28,22,910,42),"GARAGE / PARTS & LABOR",29,true);Label(new Rect(1000,27,240,36),Store.Profile.availableCredits.ToString("N0")+" cr",23,true);Label(new Rect(28,76,1210,54),"Remove a fitted kit into storage, or drag an owned kit back onto its matching slot. Removal and refitting each cost labor. Paid stages stay with the kit.",18);var button=new GUIStyle(GUI.skin.button){fontSize=16,wordWrap=true};GUI.backgroundColor=new Color(.13f,.29f,.32f);GUI.enabled=pendingCar==null;
 Fill(new Rect(24,142,282,544),new Color(.065f,.105f,.13f));Label(new Rect(38,151,250,30),"YOUR CARS",19,true);var cars=Store.Profile.fleet.cars.Where(c=>c.owner=="player").ToArray();carsScroll=GUI.BeginScrollView(new Rect(33,190,264,485),carsScroll,new Rect(0,0,242,Mathf.Max(470,cars.Length*75)));for(int i=0;i<cars.Length;i++){var c=cars[i];if(GUI.Button(new Rect(0,i*75,241,65),(FocusedCar==c.id?"SELECTED / ":"")+Model(VehicleLineup.Model(c))+"\n"+(Store.HasEngine(c.id)?"Engine fitted":"Empty engine bay"),button))Focus(c.id);}GUI.EndScrollView();
 Fill(new Rect(322,142,476,544),new Color(.065f,.105f,.13f));Label(new Rect(338,151,445,30),"FITTED ENGINE HARDWARE",19,true);var slots=new Dictionary<string,Rect>();if(FocusedCar!=null){var car=FleetLedger.Find(Store.Profile.fleet,FocusedCar);int i=0;foreach(string slot in new[]{"induction","cooling","intake","exhaust"}){var r=new Rect(338,194+i*119,445,108);slots[slot]=r;Fill(r,new Color(.09f,.17f,.20f));int stage=ComponentInventoryLedger.Stage(car.build,slot);string choice=ComponentInventoryLedger.Choice(car.build,slot);Label(new Rect(r.x+10,r.y+6,425,32),Title(slot,choice,stage),20,true);Label(new Rect(r.x+10,r.y+40,271,61),stage>0?"DRAG TO STORAGE\nMatched kit + saved stage":"Factory hardware / no separate upgraded kit",15);if(stage>0&&Store.HasEngine(car.id)){handles.Add(new Handle{rect=new Rect(r.x,r.y,280,108),slot=slot});if(GUI.Button(new Rect(r.x+286,r.y+55,149,42),"Remove · "+ComponentInventoryLedger.Labor(slot)+" cr",button))BeginRemove(car.id,slot);}i++;}}
 var storage=new Rect(814,142,442,544);Fill(storage,new Color(.065f,.105f,.13f));Label(new Rect(830,151,410,30),"STORED COMPONENTS",19,true);var parts=Store.Profile.fleet.parts.Where(p=>p.owner=="player"&&p.status=="stored").ToArray();scroll=GUI.BeginScrollView(new Rect(824,191,422,483),scroll,new Rect(0,0,400,Mathf.Max(468,parts.Length*118)));for(int i=0;i<parts.Length;i++){var p=parts[i];var r=new Rect(4,i*118,388,108);Fill(r,new Color(.10f,.22f,.25f));Label(new Rect(13,r.y+4,369,30),Title(p.slot,p.choice,p.stage),19,true);Label(new Rect(13,r.y+36,370,30),Model(p.modelId)+" · matched calibration",15);Label(new Rect(13,r.y+72,174,30),"DRAG TO SLOT",15,true);if(GUI.Button(new Rect(191,r.y+67,191,34),"Fit · "+ComponentInventoryLedger.Labor(p.slot)+" cr",button)&&FocusedCar!=null)BeginFit(p.id,FocusedCar);handles.Add(new Handle{rect=new Rect(828,191+i*118-scroll.y,180,108),part=p.id});}GUI.EndScrollView();if(parts.Length==0)Label(new Rect(840,225,383,120),"No stored kits yet. Remove a fitted turbo, supercharger, intercooler, intake or exhaust. Stock integral turbo engines cannot be stripped into aftermarket kits.",18);
 var ev=Event.current;var mouse=ev.mousePosition;if(pendingCar==null&&ev.type==EventType.MouseDown&&ev.button==0)foreach(var h in handles)if(h.rect.Contains(mouse)&&mouse.y>=194&&mouse.y<676){dragSlot=h.slot;dragPart=h.part;GUIUtility.hotControl=GUIUtility.GetControlID(FocusType.Passive);ev.Use();break;}if(dragSlot!=null||dragPart!=null){if(ev.type==EventType.MouseUp&&ev.button==0){GUIUtility.hotControl=0;if(dragSlot!=null&&storage.Contains(mouse)&&FocusedCar!=null)BeginRemove(FocusedCar,dragSlot);else if(dragPart!=null&&FocusedCar!=null){var slot=slots.FirstOrDefault(p=>p.Value.Contains(mouse));if(slot.Key!=null){if(ComponentInventoryLedger.Find(Store.Profile.fleet,dragPart).slot==slot.Key)BeginFit(dragPart,FocusedCar);else Message="Drop this kit onto its matching hardware slot.";}}dragSlot=dragPart=null;ev.Use();}else{Fill(new Rect(mouse.x+12,mouse.y+12,260,45),new Color(.08f,.5f,.45f));Label(new Rect(mouse.x+22,mouse.y+18,240,34),"COMPONENT / DROP TO MOVE",16,true);if(ev.type==EventType.MouseDrag)ev.Use();}}
 Label(new Rect(28,701,1220,43),Message??"Supporting tune, gearbox and cooler requirements still apply. Stored kits need the same engine calibration; engine swaps carry fitted kits with them.",16);if(GUI.Button(new Rect(28,752,1218,36),"Back to cars & engines",button))shop.OpenInventoryMode();GUI.enabled=true;if(pendingCar!=null){Fill(new Rect(0,0,1280,800),new Color(0,0,0,.78f));Fill(new Rect(325,246,630,300),new Color(.08f,.16f,.20f));Label(new Rect(350,267,580,43),pendingPart==null?"CONFIRM COMPONENT REMOVAL":"CONFIRM COMPONENT REFIT",24,true);Label(new Rect(350,325,580,119),(pendingPart==null?"Remove this fitted package into your inventory?":"Fit this owned package to the selected car?")+"\n\nLabor: "+fee.ToString("N0")+" cr. The kit retains its paid stage. Compatibility and supporting hardware are checked again when saving.",20);if(GUI.Button(new Rect(350,476,275,44),"Pay labor · "+fee+" cr",button))Confirm();if(GUI.Button(new Rect(650,476,275,44),"Cancel",button))pendingCar=null;}GUI.backgroundColor=color;GUI.matrix=old;}
}
